import jax.experimental.pallas as pl
import jax.experimental.pallas.triton as plt

def candidate(x):
    def kernel(x_ref, y_ref):
        v = x_ref[0, :]
        e = jnp.exp(v - jnp.max(v))
        y_ref[0, :] = e / jnp.sum(e)
    return pl.pallas_call(kernel, out_shape=jax.ShapeDtypeStruct(x.shape, x.dtype), grid=(x.shape[0],), in_specs=[pl.BlockSpec((1, x.shape[1]), lambda r: (r, 0))], out_specs=pl.BlockSpec((1, x.shape[1]), lambda r: (r, 0)), compiler_params=plt.CompilerParams(num_warps=4))(x)

