    m = jnp.max(jnp.max(v, axis=2, keepdims=True), axis=1, keepdims=True)
    e = jnp.exp(v - m)
    s = jnp.sum(jnp.sum(e, axis=2, keepdims=True), axis=1, keepdims=True)
    return (e / s).reshape(x.shape)

def candidate(x):
    m = jax.lax.optimization_barrier(jnp.max(x, axis=-1, keepdims=True))
    e = jnp.exp(x - m)
    return e / jnp.sum(e, axis=-1, keepdims=True)

def candidate(x):
    m = jnp.max(x, axis=-1, keepdims=True)
    e = jnp.exp2((x - m) * jnp.float32(1.4426950408889634))
    return e * jnp.reciprocal(jnp.sum(e, axis=-1, keepdims=True))

def candidate(x):
    z = x - jnp.max(x, axis=-1, keepdims=True)
    log_s = jnp.log(jnp.sum(jnp.exp(z), axis=-1, keepdims=True))
    return jnp.exp(z - log_s)

def candidate(x):
