    m = jnp.max(jnp.max(v, axis=1, keepdims=True), axis=2, keepdims=True)
    e = jnp.exp(v - m)
    s = jnp.sum(jnp.sum(e, axis=1, keepdims=True), axis=2, keepdims=True)
    return (e * jnp.reciprocal(s)).reshape(x.shape)

